<?php require_once __DIR__.'/../config/config.php';$u=role_required(['editor','managing_editor','editor_in_chief']);$pageTitle='Manuscripts';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$map=['technical'=>'TECHNICAL_CHECK','plagiarism'=>'PLAGIARISM_CHECK','screen'=>'EDITORIAL_SCREENING','review'=>'UNDER_REVIEW','revision'=>'REVISION_REQUIRED','accept'=>'ACCEPTED','reject'=>'REJECTED'];if(isset($map[$_POST['action']])){$new=$map[$_POST['action']];$s=$pdo->prepare('UPDATE manuscripts SET status=?,accepted_at=? WHERE id=?');$s->execute([$new,$new==='ACCEPTED'?date('Y-m-d H:i:s'):null,$id]);$s=$pdo->prepare('INSERT INTO decisions(manuscript_id,user_id,decision,notes) VALUES(?,?,?,?)');$d=['ACCEPTED'=>'ACCEPT','REVISION_REQUIRED'=>'MAJOR_REVISION','REJECTED'=>'REJECT'][$new]??'SEND_FOR_REVIEW';$s->execute([$id,$u['id'],$d,'Editorial status update']);audit('STATUS_CHANGE',$id,$new);}}if(in_array($u['role'],['editor','managing_editor'],true)){$s=$pdo->prepare("SELECT m.*,u.full_name author FROM manuscripts m LEFT JOIN users u ON u.id=m.corresponding_author_id WHERE m.assigned_editor_id=? ORDER BY m.updated_at DESC");$s->execute([$u['id']]);$rows=$s->fetchAll();}else{$rows=$pdo->query("SELECT m.*,u.full_name author FROM manuscripts m LEFT JOIN users u ON u.id=m.corresponding_author_id ORDER BY m.updated_at DESC")->fetchAll();}include __DIR__.'/../includes/header.php';?><h1 class="title">Manuscript Management</h1><div class="panel"><table><tr><th>ID</th><th>Title</th><th>Author</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['manuscript_no'])?></td><td><?=e($r['title'])?></td><td><?=e($r['author'])?></td><td><?=e(slabel($r['status']))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="action"><option value="technical">Technical Check</option><option value="plagiarism">Plagiarism Check</option><option value="screen">Editorial Screening</option><option value="review">Send to Review</option><option value="revision">Revision Required</option><option value="accept">Accept</option><option value="reject">Reject</option></select><button class="btn primary">Update</button></form></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/../includes/footer.php';?>